        static readonly Dictionary<string,int> KeyIndex=MakeIndex();
        static Dictionary<string,int> MakeIndex()
        {
            if(Packs.Length!=18 || Names.Length!=Codes.Length)throw new InvalidOperationException("Language count mismatch");
            var result=new Dictionary<string,int>();
            for(int i=0;i<Keys.Length;i++)result.Add(Keys[i],i);
            for(int i=0;i<Packs.Length;i++)if(Packs[i].Length!=Keys.Length)throw new InvalidOperationException("Language pack schema: "+Codes[i]+" "+Packs[i].Length+" != "+Keys.Length);
            return result;
        }
        public static string T(string key,params object[] values)
        {
            int index=Array.IndexOf(Codes,Code);if(index<0)index=1;
            string text;
            if(index==18)text=Xiongxin.OWTS.Localization.UiLanguage.ToTraditional(Packs[0][KeyIndex[key]]);
            else if(index!=0&&Xiongxin.OWTS.Localization.UiLanguage.TryTranslate(index,Packs[1][KeyIndex[key]],out text)){}
            else text=Packs[Xiongxin.OWTS.Localization.UiLanguage.LegacyIndex(index)][KeyIndex[key]];
            return string.Format(System.Globalization.CultureInfo.CurrentCulture,text,values);
        }
    }
